const config = $input.all()[0].json;
const departments = JSON.parse(config.departmentsJson);
const items = [];
items.push({
  json: {
    requestKind: 'vigilance',
    url: config.vigilanceEndpoint,
    generatedAt: config.generatedAt,
  }
});
for (const dept of departments) {
  items.push({
    json: {
      requestKind: 'observations',
      url: `${config.observationsBaseUrl}/paquet/horaire?format=json&id-departement=${encodeURIComponent(dept.code)}`,
      departmentCode: dept.code,
      departmentName: dept.name,
      departmentRideDaysJson: JSON.stringify(dept.rideDays),
      generatedAt: config.generatedAt,
    }
  });
}
return items;

const severityByRiskCode = { '1': 'green', '2': 'yellow', '3': 'orange', '4': 'red' };
const phenomenonById = { '1': 'Wind', '2': 'Rain-flooding', '3': 'Thunderstorms', '4': 'Flooding', '5': 'Snow-ice', '6': 'Heat', '7': 'Cold', '8': 'Avalanche', '9': 'Coastal flooding' };
const heatBandBySeverity = {
  yellow: { titleContext: 'brief heat spike or prolonged warmth below heatwave level', explanation: 'Météo-France yellow heat vigilance means a brief heat spike or prolonged warmth below official heatwave thresholds.' },
  orange: { titleContext: 'official heatwave; hot days and warm nights', explanation: 'Météo-France orange heat vigilance means official heatwave conditions, with high daytime temperatures and warm nights.' },
  red: { titleContext: 'extreme heatwave; highs may reach 104°F/40°C+', explanation: 'Météo-France red heat vigilance means an extreme heatwave, with dangerous temperatures affecting the entire population.' },
};
function titleCase(v) { return v.charAt(0).toUpperCase() + v.slice(1); }
function condensedHazardLabel(v) { return v.toLowerCase().replace(/\s+/g, ' '); }
function genericVigilanceExplanation(severity, hazard) {
  const hazardLabel = condensedHazardLabel(hazard);
  return {
    yellow: `Météo-France yellow ${hazardLabel} vigilance means a localized or short-lived risk that still requires attention in this department.`,
    orange: `Météo-France orange ${hazardLabel} vigilance means dangerous conditions are expected and this department is under heightened official alert.`,
    red: `Météo-France red ${hazardLabel} vigilance means exceptional conditions with major impacts expected across the affected department.`,
  }[severity];
}
function buildStatusDetails({ severity, departmentName, phenomena, checkedAt }) {
  const primaryHazard = phenomena[0] || 'Official weather warning';
  const heatAlert = phenomena.includes('Heat');
  if (heatAlert) {
    const band = heatBandBySeverity[severity];
    return {
      statusTitle: `${titleCase(severity)} heat warning in ${departmentName} (${band.titleContext}).`,
      statusExplanation: band.explanation,
      statusSource: { name: 'Météo-France Vigilance', url: 'https://vigilance.meteofrance.fr/fr', official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
    };
  }
  const hazardPhrase = condensedHazardLabel(primaryHazard);
  return {
    statusTitle: `${titleCase(severity)} ${hazardPhrase} warning in ${departmentName} (official departmental vigilance).`,
    statusExplanation: genericVigilanceExplanation(severity, primaryHazard),
    statusSource: { name: 'Météo-France Vigilance', url: 'https://vigilance.meteofrance.fr/fr', official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
  };
}

const config = $items('Set Connector Config')[0].json;
const departments = JSON.parse(config.departmentsJson);
const departmentByCode = new Map(departments.map((d) => [d.code, d]));
const checkedAt = new Date().toISOString();

const inputItems = $input.all();
if (!inputItems.length) {
  return [{ json: { recordKind: 'sourceHealth', sourceId: 'meteo-france-vigilance', sourceName: 'Météo-France Vigilance', status: 'failed', fetchedAt: checkedAt, staleAfterMinutes: Number(config.vigilanceStaleAfterMinutes), httpStatus: 0, recordCount: 0, errors: ['No Vigilance request reached this node'], warnings: [] } }];
}
const raw = inputItems[0].json || {};
const status = Number(raw.statusCode || 0);
const bodyText = String(raw.data ?? raw.body ?? '');

if (!status || status < 200 || status >= 300 || !bodyText) {
  return [{ json: { recordKind: 'sourceHealth', sourceId: 'meteo-france-vigilance', sourceName: 'Météo-France Vigilance', status: 'failed', fetchedAt: checkedAt, staleAfterMinutes: Number(config.vigilanceStaleAfterMinutes), httpStatus: status || 0, recordCount: 0, errors: ['Vigilance fetch failed or returned an empty body'], warnings: [] } }];
}

let payload;
try {
  payload = JSON.parse(bodyText);
} catch (err) {
  return [{ json: { recordKind: 'sourceHealth', sourceId: 'meteo-france-vigilance', sourceName: 'Météo-France Vigilance', status: 'failed', fetchedAt: checkedAt, staleAfterMinutes: Number(config.vigilanceStaleAfterMinutes), httpStatus: status, recordCount: 0, errors: ['Vigilance response was not valid JSON: ' + err.message], warnings: [] } }];
}

function collectDepartmentRisks(product) {
  const periods = (product && product.periods) || [];
  const rows = [];
  periods.forEach((period, periodIndex) => {
    const domains = (period.timelaps && period.timelaps.domain_ids) || {};
    for (const dept of departments) {
      const domain = domains[dept.code];
      if (!domain) continue;
      const riskCode = String(domain.max_color_id || '');
      if (!severityByRiskCode[riskCode]) continue;
      rows.push({
        departmentCode: dept.code,
        periodIndex,
        riskCode,
        phenomenonItems: Array.isArray(domain.phenomenon_items) ? domain.phenomenon_items.filter((item) => Number(item.phenomenon_max_color_id) > 1) : [],
        beginValidityTime: period.begin_validity_time || product.update_time,
        endValidityTime: period.end_validity_time || null,
      });
    }
  });
  return rows;
}

const risks = collectDepartmentRisks(payload.product).filter((r) => r.riskCode !== '1');
const records = [];
for (const risk of risks) {
  const department = departmentByCode.get(risk.departmentCode);
  if (!department) continue;
  const phenomenonTimes = risk.phenomenonItems.flatMap((item) => (Array.isArray(item.timelaps_items) ? item.timelaps_items : []));
  const phenomena = risk.phenomenonItems
    .map((item) => phenomenonById[String(item.phenomenon_id)] || item.phenomenon_name || `Phenomenon ${item.phenomenon_id}`)
    .filter(Boolean);
  const phenomenonText = phenomena.length ? phenomena.join(', ') : 'Official weather warning';
  const startTime = phenomenonTimes.map((item) => item.begin_time).filter(Boolean).sort()[0] || risk.beginValidityTime || (payload.product && payload.product.update_time) || checkedAt;
  const expectedEndTimeCandidates = phenomenonTimes.map((item) => item.end_time).filter(Boolean).sort();
  const expectedEndTime = expectedEndTimeCandidates.length ? expectedEndTimeCandidates[expectedEndTimeCandidates.length - 1] : risk.endValidityTime;
  const severity = severityByRiskCode[risk.riskCode];
  const statusDetails = buildStatusDetails({ severity, departmentName: department.name, phenomena, checkedAt });
  for (const rideDay of department.rideDays) {
    records.push({
      json: {
        recordKind: 'vigilance',
        externalId: `meteo-france-vigilance-${risk.departmentCode}-p${risk.periodIndex}-${risk.riskCode}-${rideDay}`,
        sourceId: 'meteo-france-vigilance',
        category: 'weather',
        severity,
        status: 'forecast',
        title: statusDetails.statusTitle,
        nearestPlace: department.name,
        rideDay,
        distanceFromRouteKm: null,
        routeInfluenceConfirmed: true,
        startTime,
        expectedEndTime,
        checkedAt,
        sourceUrl: 'https://vigilance.meteofrance.fr/fr',
        summary: `${department.name} is under ${severity} Météo-France Vigilance for ${phenomenonText}.`,
        statusTitle: statusDetails.statusTitle,
        statusExplanation: statusDetails.statusExplanation,
        statusSource: statusDetails.statusSource,
        whyItMatters: 'The warning applies at department level and overlaps one or more planned riding days.',
        recommendedAction: 'Review the official bulletin and timing before riding the affected day.',
        suggestedDetour: null,
        detourImpact: null,
      },
    });
  }
}

records.push({
  json: {
    recordKind: 'sourceHealth', sourceId: 'meteo-france-vigilance', sourceName: 'Météo-France Vigilance',
    status: 'ok', fetchedAt: checkedAt, staleAfterMinutes: Number(config.vigilanceStaleAfterMinutes),
    httpStatus: status, recordCount: records.length, errors: [], warnings: [],
  },
});
return records;

function celsiusFromKelvin(v) { return Number.isFinite(v) ? v - 273.15 : null; }
function fahrenheitFromCelsius(c) { return Math.round((c * 9) / 5 + 32); }
function msToKmh(v) { return v * 3.6; }
function kmhToMph(v) { return Math.round(v * 0.621371); }
function mmToIn(v) { return (v / 25.4).toFixed(2); }
function kmToMi(v) { return (v * 0.621371).toFixed(1); }
function groundStateLabel(code) {
  return { 1: 'wet ground', 2: 'standing water on ground', 3: 'flooded ground', 4: 'frozen ground', 5: 'ice on ground', 9: 'very dry cracked ground' }[Number(code)] || null;
}

const config = $items('Set Connector Config')[0].json;
const checkedAt = new Date().toISOString();
const requestMeta = $items('Observations Requests');
const inputItems = $input.all();

function makeAlert({ department, rideDay, kind, severity, title, summary, whyItMatters, recommendedAction, statusExplanation, record }) {
  return {
    recordKind: 'observations',
    externalId: `meteo-france-observations-${kind}-${record.geo_id_insee}-${record.validity_time}-${rideDay}`,
    sourceId: 'meteo-france-observations',
    category: kind === 'ground' ? 'surface' : 'weather',
    severity, status: 'confirmed', title,
    nearestPlace: record.geo_id_insee, latitude: record.lat, longitude: record.lon,
    rideDay, distanceFromRouteKm: null, routeInfluenceConfirmed: true,
    startTime: record.validity_time, expectedEndTime: null, checkedAt,
    sourceUrl: 'https://meteofrance.com/', statusTitle: title, statusExplanation,
    statusSource: { name: 'Météo-France Observations', url: 'https://meteofrance.com/', official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
    summary, whyItMatters, recommendedAction, suggestedDetour: null, detourImpact: null,
  };
}

function alertsForRecord(record, department) {
  const alerts = [];
  const tempC = celsiusFromKelvin(Number(record.t));
  if (tempC !== null && tempC >= 30) {
    const severity = tempC >= 35 ? 'orange' : 'yellow';
    alerts.push({ kind: 'temperature', severity, title: `Measured heat near route: ${Math.round(tempC)}°C / ${fahrenheitFromCelsius(tempC)}°F`, summary: `Météo-France measured ${Math.round(tempC)}°C / ${fahrenheitFromCelsius(tempC)}°F at ${record.validity_time}.`, statusExplanation: `Météo-France measured ${Math.round(tempC)}°C near ${department.name}, confirming ${severity === 'orange' ? 'severe' : 'notable'} current heat rather than only a forecast warning.`, whyItMatters: 'Measured heat confirms current conditions near the route, not just forecast risk.', recommendedAction: 'Check timing, water availability and shade for the affected riding day.' });
  }
  const gustKmh = Number.isFinite(Number(record.raf)) ? msToKmh(Number(record.raf)) : null;
  if (gustKmh !== null && gustKmh >= 40) {
    const severity = gustKmh >= 55 ? 'orange' : 'yellow';
    alerts.push({ kind: 'gust', severity, title: `Measured gusts near route: ${Math.round(gustKmh)} km/h / ${kmhToMph(gustKmh)} mph`, summary: `Météo-France measured gusts of ${Math.round(gustKmh)} km/h / ${kmhToMph(gustKmh)} mph at ${record.validity_time}.`, statusExplanation: `Météo-France measured ${Math.round(gustKmh)} km/h gusts near ${department.name}, confirming wind strong enough to affect exposed sections.`, whyItMatters: 'Measured gusts can affect exposed road and canal sections.', recommendedAction: 'Check exposed segments and bridges before riding the affected day.' });
  }
  const rainMm = Number(record.rr1);
  if (Number.isFinite(rainMm) && rainMm > 0) {
    alerts.push({ kind: 'rain', severity: rainMm >= 5 ? 'orange' : 'yellow', title: `Measured rain near route: ${rainMm.toFixed(1)} mm / ${mmToIn(rainMm)} in`, summary: `Météo-France measured ${rainMm.toFixed(1)} mm / ${mmToIn(rainMm)} in of rain in the last hour at ${record.validity_time}.`, statusExplanation: `Météo-France measured ${rainMm.toFixed(1)} mm of recent rain near ${department.name}, indicating wetter surfaces and reduced visibility.`, whyItMatters: 'Recent measured rain can mean wet surfaces, reduced visibility and localized standing water.', recommendedAction: 'Check surfaces and low points on the affected riding day.' });
  }
  const visibilityKm = Number.isFinite(Number(record.vv)) && Number(record.vv) > 0 ? Number(record.vv) / 1000 : null;
  if (visibilityKm !== null && visibilityKm < 2) {
    alerts.push({ kind: 'visibility', severity: visibilityKm < 1 ? 'orange' : 'yellow', title: `Measured visibility near route: ${visibilityKm.toFixed(1)} km / ${kmToMi(visibilityKm)} mi`, summary: `Météo-France measured visibility of ${visibilityKm.toFixed(1)} km / ${kmToMi(visibilityKm)} mi at ${record.validity_time}.`, statusExplanation: `Météo-France measured visibility below ${visibilityKm.toFixed(1)} km near ${department.name}, confirming reduced sight distance for crossings and traffic.`, whyItMatters: 'Low visibility affects road crossings, traffic exposure and navigation.', recommendedAction: 'Use lights and verify whether the affected section should be delayed.' });
  }
  const groundLabel = groundStateLabel(record.etat_sol);
  if (groundLabel) {
    const code = Number(record.etat_sol);
    const severity = code === 3 || code === 5 ? 'red' : code === 4 ? 'orange' : 'yellow';
    alerts.push({ kind: 'ground', severity, title: `Measured ground state near route: ${groundLabel}`, summary: `Météo-France reported ${groundLabel} at ${record.validity_time}.`, statusExplanation: `Météo-France reported ${groundLabel} near ${department.name}, confirming current surface conditions that may materially affect traction.`, whyItMatters: 'Ground state is a measured surface condition that may affect traction or passability.', recommendedAction: 'Verify the nearby route surface before riding through this area.' });
  }
  return alerts;
}

const severityRank = { yellow: 1, orange: 2, red: 3 };
const bestByKey = new Map();
let okResponses = 0;
let failedResponses = 0;

for (let index = 0; index < inputItems.length; index++) {
  const raw = inputItems[index].json || {};
  const meta = (requestMeta[index] && requestMeta[index].json) || {};
  const status = Number(raw.statusCode || 0);
  const bodyText = String(raw.data ?? raw.body ?? '');
  if (!status || status < 200 || status >= 300 || !bodyText) { failedResponses++; continue; }
  let records;
  try {
    records = JSON.parse(bodyText);
  } catch (err) {
    failedResponses++;
    continue;
  }
  if (!Array.isArray(records)) { failedResponses++; continue; }
  okResponses++;
  const department = { code: meta.departmentCode, name: meta.departmentName, rideDays: JSON.parse(meta.departmentRideDaysJson || '[]') };
  for (const record of records) {
    if (!Number.isFinite(record.lat) || !Number.isFinite(record.lon) || !record.validity_time) continue;
    const alerts = alertsForRecord(record, department);
    for (const alert of alerts) {
      for (const rideDay of department.rideDays) {
        const key = `${rideDay}-${alert.kind}`;
        const rank = severityRank[alert.severity] || 0;
        const current = bestByKey.get(key);
        const currentRank = current ? (severityRank[current.alert.severity] || 0) : 0;
        if (!current || rank > currentRank || (rank === currentRank && new Date(record.validity_time) > new Date(current.record.validity_time))) {
          bestByKey.set(key, { alert, record, department, rideDay });
        }
      }
    }
  }
}

const output = [];
for (const { alert, record, department, rideDay } of bestByKey.values()) {
  output.push({
    json: makeAlert({
      department, rideDay, kind: alert.kind, severity: alert.severity, title: alert.title,
      summary: alert.summary, whyItMatters: alert.whyItMatters, recommendedAction: alert.recommendedAction,
      statusExplanation: alert.statusExplanation, record,
    }),
  });
}

const healthStatus = failedResponses > 0 && okResponses === 0 ? 'failed' : (failedResponses > 0 ? 'degraded' : 'ok');
output.push({
  json: {
    recordKind: 'sourceHealth', sourceId: 'meteo-france-observations', sourceName: 'Météo-France Observations',
    status: healthStatus, fetchedAt: checkedAt, staleAfterMinutes: Number(config.observationsStaleAfterMinutes),
    httpStatus: okResponses > 0 ? 200 : 0, recordCount: output.length,
    errors: healthStatus === 'failed' ? ['All department observation requests failed or returned invalid data'] : [],
    warnings: failedResponses > 0 && okResponses > 0 ? [`${failedResponses} of ${inputItems.length} department requests failed`] : [],
  },
});
return output;

const requiredRecordFields = ['externalId', 'sourceId', 'category', 'severity', 'status', 'title', 'checkedAt', 'statusTitle', 'statusExplanation', 'statusSource'];
const severityEnum = ['green', 'yellow', 'orange', 'red'];
const sourceHealthRequired = ['sourceId', 'sourceName', 'status', 'fetchedAt', 'staleAfterMinutes', 'httpStatus', 'recordCount', 'errors', 'warnings'];
function validIso(v) { return !v || !Number.isNaN(Date.parse(v)); }
function looksLikeSecret(v) {
  if (typeof v !== 'string') return false;
  return /^[A-Za-z0-9_-]{24,}$/.test(v) && !/^https?:\/\//.test(v);
}

const config = $items('Set Connector Config')[0].json;
const errors = [];
const out = [];

for (const item of $input.all()) {
  const r = item.json || {};
  if (r.recordKind === 'sourceHealth') {
    for (const field of sourceHealthRequired) {
      if (r[field] === undefined || r[field] === null) errors.push(`sourceHealth ${r.sourceId || 'unknown'} missing ${field}`);
    }
    if (!validIso(r.fetchedAt)) errors.push(`sourceHealth ${r.sourceId} has invalid fetchedAt`);
    if (!['ok', 'degraded', 'failed', 'stale'].includes(r.status)) errors.push(`sourceHealth ${r.sourceId} has invalid status enum: ${r.status}`);
    out.push(item);
    continue;
  }
  const recErrors = [];
  for (const field of requiredRecordFields) {
    if (r[field] === undefined || r[field] === null || r[field] === '') recErrors.push('Missing required field: ' + field);
  }
  if (r.severity && !severityEnum.includes(r.severity)) recErrors.push('Invalid severity enum: ' + r.severity);
  if (!validIso(r.checkedAt) || !validIso(r.startTime)) recErrors.push('Invalid ISO timestamp');
  if (['yellow', 'orange', 'red'].includes(r.severity) && (!r.statusSource || r.statusSource.official !== true)) {
    recErrors.push('Elevated severity requires statusSource.official === true');
  }
  if (recErrors.length) errors.push(...recErrors.map((e) => `${r.recordKind || 'record'}/${r.externalId || 'unknown'}: ${e}`));
  out.push({ json: { ...r, validationErrors: recErrors } });
}

if (!config.connectorId) errors.push('Missing connectorId in Set Connector Config');
if (!validIso(config.generatedAt)) errors.push('Missing or invalid generatedAt in Set Connector Config');
if (!config.outputDirectory || !config.outputDirectory.startsWith('/files/cdm-status-output')) {
  errors.push('Forbidden or missing output directory: expected /files/cdm-status-output');
}

return [{ json: { recordKind: 'validationResult', passed: errors.length === 0, errors, warnings: [] } }, ...out];

const config = $items('Set Connector Config')[0].json;
const items = $input.all().map((item) => item.json || {});
const validationResult = items.find((item) => item.recordKind === 'validationResult') || { passed: true, errors: [], warnings: [] };
const validationErrors = Array.isArray(validationResult.errors) ? validationResult.errors : [];
const validationWarnings = Array.isArray(validationResult.warnings) ? validationResult.warnings : [];
const vigilance = items.filter((item) => item.recordKind === 'vigilance');
const observations = items.filter((item) => item.recordKind === 'observations');
const sourceHealth = items.filter((item) => item.recordKind === 'sourceHealth');
const records = [...vigilance, ...observations];
const sourceDescriptors = [
  {
    sourceId: 'meteo-france-vigilance',
    sourceName: 'Météo-France Vigilance',
    endpoint: config.vigilanceEndpoint,
    category: 'weather',
  },
  {
    sourceId: 'meteo-france-observations',
    sourceName: 'Météo-France Observations',
    endpoint: config.observationsBaseUrl + '/paquet/horaire',
    category: 'weather',
  },
];

const sourceWarnings = sourceHealth.flatMap((item) => Array.isArray(item.warnings) ? item.warnings : []);
const sourceErrors = sourceHealth.flatMap((item) => Array.isArray(item.errors) ? item.errors : []);
const warnings = [...validationWarnings, ...sourceWarnings];
const errors = [...validationErrors, ...sourceErrors];
const allSourcesOk = sourceHealth.length === sourceDescriptors.length && sourceHealth.every((item) => item.status === 'ok');
const stale = sourceHealth.some((item) => item.status === 'stale');
const sourceUpdatedCandidates = sourceHealth.map((item) => item.fetchedAt).filter((value) => value && !Number.isNaN(Date.parse(value)));
const sourceUpdatedAt = sourceUpdatedCandidates.length
  ? new Date(Math.max(...sourceUpdatedCandidates.map((value) => new Date(value).getTime()))).toISOString()
  : null;
const completedAt = new Date().toISOString();
const startedAt = config.startedAt || config.generatedAt || completedAt;
const promotionEligible = validationResult.passed === true && allSourcesOk;
const contractStatus = promotionEligible
  ? (warnings.length > 0 ? 'SUCCESS_WITH_WARNINGS' : 'SUCCESS')
  : 'FAILED_NO_OUTPUT';

const combined = {
  connectorId: config.connectorId,
  connectorName: config.connectorName,
  generatedAt: config.generatedAt,
  timezone: config.timezone,
  status: validationResult.passed === true
    ? (allSourcesOk ? 'ok' : 'failed')
    : 'failed',
  sources: sourceDescriptors,
  vigilance,
  observations,
  records,
  sourceHealth,
  validation: {
    passed: validationResult.passed === true,
    errors: validationErrors,
    warnings: validationWarnings,
  },
  compatibility: {
    targetCurrentFeed: 'public/cdm-monitoring-status.json',
    mode: 'compatibility_candidate',
  },
};

const payload = {
  schema_version: '1.0.0',
  connector_id: config.connectorId,
  connector_name: config.connectorName,
  run_id: String(config.runId || ''),
  status: contractStatus,
  started_at: startedAt,
  completed_at: completedAt,
  generated_at: config.generatedAt || startedAt,
  source_updated_at: sourceUpdatedAt,
  record_count: records.length,
  source_count: sourceDescriptors.length,
  sources: sourceDescriptors.map((item) => ({ name: item.sourceName, url: item.endpoint })),
  data: combined,
  warnings,
  errors,
  stale,
  last_known_good: {
    is_last_known_good: false,
    reason: promotionEligible
      ? 'Fresh output generated and promoted atomically.'
      : 'Candidate output was not promoted because source fetches or validation checks failed.',
  },
  validation: {
    schema_valid: validationResult.passed === true,
    passed: validationResult.passed === true,
    errors: validationErrors,
    warnings: validationWarnings,
  },
  connectorId: combined.connectorId,
  connectorName: combined.connectorName,
  generatedAt: combined.generatedAt,
  timezone: combined.timezone,
  source_status: combined.status,
  vigilance: combined.vigilance,
  observations: combined.observations,
  records: combined.records,
  sourceHealth: combined.sourceHealth,
  compatibility: combined.compatibility,
};

return [
  {
    json: {
      outputDirectory: config.outputDirectory,
      finalPath: config.finalOutputPath,
      stagingPath: config.stagingOutputPath,
      renameCommand: `mv "${config.stagingOutputPath}" "${config.finalOutputPath}"`,
      jsonText: JSON.stringify(payload, null, 2) + '\n',
      promotionEligible,
      warnings,
      errors,
    },
  },
];

const output = [];
for (const item of $input.all()) {
  const buf = Buffer.from(item.json.jsonText, 'utf8');
  const fileName = String(item.json.targetPath).split('/').pop();
  const binary = await this.helpers.prepareBinaryData(buf, fileName, 'application/json');
  output.push({ json: item.json, binary: { data: binary } });
}
return output;

const item = $input.first();
if (!item || !item.binary || !item.binary.data) {
  throw new Error('No staged file binary data was available for validation.');
}

const config = $items('Set Connector Config')[0].json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const text = buffer.toString('utf8');
let parsed;
try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error('Staged weather output is not valid JSON: ' + error.message);
}

const requiredFields = [
  'schema_version',
  'connector_id',
  'connector_name',
  'run_id',
  'status',
  'started_at',
  'completed_at',
  'generated_at',
  'source_updated_at',
  'record_count',
  'source_count',
  'sources',
  'data',
  'warnings',
  'errors',
  'stale',
  'last_known_good',
  'validation',
];

const missing = requiredFields.filter((field) => !(field in parsed));
if (missing.length > 0) {
  throw new Error('Staged weather output is missing required top-level fields: ' + missing.join(', '));
}

if (parsed.schema_version !== '1.0.0') {
  throw new Error('Unexpected schema_version in staged weather output: ' + parsed.schema_version);
}

if (!Array.isArray(parsed.sources) || !Array.isArray(parsed.warnings) || !Array.isArray(parsed.errors)) {
  throw new Error('Staged weather output does not satisfy array requirements for sources/warnings/errors.');
}

if (!parsed.validation || parsed.validation.schema_valid !== true) {
  throw new Error('Staged weather output failed schema validation.');
}

if (parsed.status === 'FAILED_NO_OUTPUT') {
  const details = [...(parsed.errors || []), ...(parsed.warnings || [])].join(' | ');
  throw new Error('Candidate weather output is not eligible for promotion. ' + details);
}

return [
  {
    json: {
      finalPath: config.finalOutputPath,
      stagingPath: config.stagingOutputPath,
      renameCommand: `mv "${config.stagingOutputPath}" "${config.finalOutputPath}"`,
      validatedAt: new Date().toISOString(),
      stagedBytes: Buffer.byteLength(text, 'utf8'),
    },
  },
];

const item = $input.first();
if (!item || !item.binary || !item.binary.data) {
  throw new Error('Final weather output file could not be read back for verification.');
}

const finalPath = item.json.finalPath || 'unknown';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const text = buffer.toString('utf8');
let parsed;
try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error('Final weather output is not valid JSON: ' + error.message);
}

const requiredFields = [
  'schema_version',
  'connector_id',
  'connector_name',
  'run_id',
  'status',
  'started_at',
  'completed_at',
  'generated_at',
  'source_updated_at',
  'record_count',
  'source_count',
  'sources',
  'data',
  'warnings',
  'errors',
  'stale',
  'last_known_good',
  'validation',
];

const missing = requiredFields.filter((field) => !(field in parsed));
if (missing.length > 0) {
  throw new Error('Final weather output is missing required fields: ' + missing.join(', '));
}

if (!parsed.validation || parsed.validation.schema_valid !== true) {
  throw new Error('Final weather output reported schema_valid !== true.');
}

return [
  {
    json: {
      recordKind: 'runDiagnostics',
      ok: true,
      generatedAt: parsed.generated_at,
      completedAt: parsed.completed_at,
      validationStatus: 'passed',
      writeStatus: 'promoted',
      infraBlocked: false,
      outputFilenames: [finalPath],
      finalPath,
      bytes: Buffer.byteLength(text, 'utf8'),
      status: parsed.status,
      sourceCount: parsed.source_count,
      recordCount: parsed.record_count,
      warnings: Array.isArray(parsed.warnings) ? parsed.warnings : [],
      errors: [],
      note: 'Weather output validated from staging file and promoted with mv.',
    },
  },
];

const config = $items('Set Connector Config')[0].json;
const commandResult = $input.first().json || {};
return [
  {
    json: {
      finalPath: config.finalOutputPath,
      renameExitCode: commandResult.exitCode,
      renameStdout: commandResult.stdout || '',
      renameStderr: commandResult.stderr || '',
    },
  },
];
